namespace Axpense.Api.Domain;
public class Organization { public Guid Id {get;set;}=Guid.NewGuid(); public string Name {get;set;}=""; public DateTime CreatedAtUtc {get;set;}=DateTime.UtcNow; public ICollection<User> Users {get;set;}=[]; public ICollection<Vehicle> Vehicles {get;set;}=[]; }
public class User { public Guid Id {get;set;}=Guid.NewGuid(); public Guid OrganizationId {get;set;} public string FullName {get;set;}=""; public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; public string Role {get;set;}="User"; public bool IsActive {get;set;}=true; public DateTime CreatedAtUtc {get;set;}=DateTime.UtcNow; public Organization Organization {get;set;}=null!; }
public abstract class TenantEntity { public Guid Id {get;set;}=Guid.NewGuid(); public Guid OrganizationId {get;set;} }
public class Vehicle:TenantEntity { public string PlateNumber {get;set;}=""; public string Make {get;set;}=""; public string Model {get;set;}=""; public int ModelYear {get;set;} public string? Vin {get;set;} public decimal? PurchasePrice {get;set;} public DateTime? PurchaseDate {get;set;} public decimal? CurrentOdometer {get;set;} public decimal? ExpectedResidualValue {get;set;} public string Status {get;set;}="Active"; public string? Notes {get;set;} public Organization Organization {get;set;}=null!; }
